

# This file was *autogenerated* from the file /workspace/leanproject/Submission/find_crt_counterexample_fixed.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_40 = Integer(40); _sage_const_10 = Integer(10); _sage_const_16 = Integer(16); _sage_const_4 = Integer(4); _sage_const_9 = Integer(9); _sage_const_160 = Integer(160); _sage_const_3 = Integer(3); _sage_const_300 = Integer(300); _sage_const_8 = Integer(8); _sage_const_5 = Integer(5); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_0p01 = RealNumber('0.01'); _sage_const_1p27 = RealNumber('1.27'); _sage_const_24 = Integer(24); _sage_const_15 = Integer(15)
import sys
import time

def precompute_V():
    V = {_sage_const_1 }
    for s in range(_sage_const_40 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        for i in range(_sage_const_160 ):
            val = fs * _sage_const_4 **i
            V.add(val)
    return sorted(list(V))

all_V = precompute_V()

def find_counterexample(num_primes):
    print(f"\n==========================================")
    print(f"Running search with {num_primes} primes...")
    
    # Primes pool
    primes_pool = [p for p in prime_range(_sage_const_3 , _sage_const_300 ) if p % _sage_const_4  == _sage_const_3 ]
    
    N_max = _sage_const_10 **_sage_const_8 
    # Iterative optimization to match N_max with base_prod
    for iteration in range(_sage_const_5 ):
        limit = N_max * N_max
        V_target = [v for v in all_V if v < limit]
        
        selected_primes = []
        selected_residues = {}
        uncovered = list(V_target)
        
        for _ in range(num_primes):
            best_p = None
            best_r = None
            best_cov = -_sage_const_1 
            
            for p in primes_pool:
                if p in selected_primes:
                    continue
                cov_for_r = [_sage_const_0 ] * p
                for v in uncovered:
                    v_mod = v % p
                    if v_mod == _sage_const_0 :
                        cov_for_r[_sage_const_0 ] += _sage_const_1 
                    elif pow(v_mod, (p-_sage_const_1 )//_sage_const_2 , p) == _sage_const_1 :
                        for r in range(_sage_const_1 , p):
                            if (r*r) % p == v_mod:
                                cov_for_r[r] += _sage_const_1 
                                cov_for_r[p-r] += _sage_const_1 
                                break
                max_cov = max(cov_for_r)
                best_r_for_p = cov_for_r.index(max_cov)
                if max_cov > best_cov:
                    best_cov = max_cov
                    best_p = p
                    best_r = best_r_for_p
                    
            if best_cov <= _sage_const_0 :
                break
                
            selected_primes.append(best_p)
            selected_residues[best_p] = best_r
            new_uncovered = []
            r2 = (best_r * best_r) % best_p
            for v in uncovered:
                if v % best_p != r2:
                    new_uncovered.append(v)
            uncovered = new_uncovered
            
        moduli = [_sage_const_2 ] + selected_primes
        residues = [_sage_const_1 ] + [selected_residues[p] for p in selected_primes]
        from math import prod as math_prod
        base_prod = math_prod(moduli)
        
        # We want N_max to be at least 2 * base_prod to cover k=0 and k=1
        new_N_max = _sage_const_2  * base_prod
        if abs(new_N_max - N_max) < _sage_const_0p01  * N_max:
            # Converged!
            break
        N_max = new_N_max
        
    N0 = int(crt(residues, moduli))
    print(f"Converged after {iteration+_sage_const_1 } iterations.")
    print(f"Selected Primes: {selected_primes}")
    print(f"Selected Residues: {[selected_residues[p] for p in selected_primes]}")
    print(f"CRT base: N0 = {N0}, prod = {base_prod}, digits = {len(str(base_prod))}")
    print(f"V_target size = {len(V_target)}, uncovered remaining = {len(uncovered)}")
    
    # Now check k = 0, 1, 2
    start_time = time.time()
    for k in range(_sage_const_5 ):
        N = N0 + k * base_prod
        if N <= _sage_const_1 :
            continue
        if N >= _sage_const_1p27  * _sage_const_10 **_sage_const_24 :
            break
            
        N2 = N * N
        V_actual = [v for v in all_V if v < N2]
        
        all_blocked = True
        blocking_primes = {}
        for v in V_actual:
            diff = N2 - v
            found_p = None
            for p in selected_primes:
                if diff % p == _sage_const_0  and diff % (p*p) != _sage_const_0 :
                    found_p = p
                    break
            if found_p is None:
                factors = factor(diff)
                for p, exp in factors:
                    if p % _sage_const_4  == _sage_const_3  and exp % _sage_const_2  != _sage_const_0 :
                        found_p = int(p)
                        break
            if found_p is not None:
                blocking_primes[v] = found_p
            else:
                all_blocked = False
                break
                
        if all_blocked:
            print(f"SUCCESS! Found N = {N} (k = {k}) in {time.time() - start_time:.2f}s")
            print(f"N^2 = {N2}")
            print(f"V_all size = {len(V_actual)}")
            print(f"blocking_primes = {blocking_primes}")
            return N, blocking_primes
            
    print("No counterexample found for this base.")
    return None

for num in range(_sage_const_4 , _sage_const_15 ):
    res = find_counterexample(num)
    if res:
        N, bp = res
        with open("/workspace/leanproject/Submission/success_sage_found.py", "w") as f:
            f.write(f"N = {N}\n")
